"""Four synchronized original RGB source streams for overtaking probes."""

from __future__ import annotations

import subprocess
from pathlib import Path
from threading import Condition
from time import monotonic


CAMERAS = {
    "overview": ((-9, 0, 8), (-12, 0, 0), (1920, 1080), 95),
    "approach": ((1.2, 0, 2), (0, 0, 0), (1280, 720), 90),
    "reference_corner": ((-3, 2.5, 2.6), (-7, 0, 0), (1280, 720), 100),
    "driver_reference": ((0.6, -0.35, 1.6), (0, 0, 0), (1280, 720), 85),
}


class LosslessSourceSink:
    def __init__(self, output, name, *, popen=subprocess.Popen):
        if name not in CAMERAS:
            raise ValueError("Unknown overtake source camera")
        path = Path(output) / (name + ".mkv")
        if path.exists():
            raise ValueError("Retain prior exposure camera source")
        width, height = CAMERAS[name][2]
        self.frame_bytes = width * height * 4
        self.process = popen(["ffmpeg", "-nostdin", "-loglevel", "error", "-y",
                              "-f", "rawvideo", "-pixel_format", "bgra",
                              "-video_size", f"{width}x{height}", "-framerate", "20",
                              "-i", "pipe:0", "-an", "-c:v", "ffv1", str(path)],
                             stdin=subprocess.PIPE)
        self.closed = False

    def write(self, image):
        if self.closed or len(image.raw_data) != self.frame_bytes:
            raise ValueError("Original overtake camera byte count changed")
        self.process.stdin.write(image.raw_data)

    def close(self):
        if not self.closed:
            self.closed = True
            self.process.stdin.close()
            if self.process.wait() != 0:
                raise ValueError("Overtake source encoder failed")


class OvertakeCameraCapture:
    def __init__(self, world, carla_module, ego, sinks):
        if set(sinks) != set(CAMERAS):
            raise ValueError("Exactly four named overtake source sinks required")
        self.sinks = sinks
        self.frames = {name: set() for name in CAMERAS}
        self.condition = Condition()
        self.errors = []
        self.sensors = []
        self.closed = False
        try:
            for name, (loc, rot, size, fov) in CAMERAS.items():
                blueprint = world.get_blueprint_library().find("sensor.camera.rgb")
                for key, value in (("image_size_x", size[0]), ("image_size_y", size[1]),
                                   ("fov", fov), ("sensor_tick", 0.05)):
                    blueprint.set_attribute(key, str(value))
                transform = carla_module.Transform(
                    carla_module.Location(*loc), carla_module.Rotation(*rot))
                sensor = world.spawn_actor(blueprint, transform, attach_to=ego)
                self.sensors.append(sensor)
                sensor.listen(lambda image, source=name: self._receive(source, image))
        except BaseException:
            self.close()
            raise

    def _receive(self, name, image):
        with self.condition:
            if self.closed:
                return
            try:
                if image.frame in self.frames[name]:
                    raise ValueError("Duplicate original overtake camera frame")
                if (image.width, image.height) != CAMERAS[name][2]:
                    raise ValueError("Original overtake camera dimensions changed")
                self.sinks[name].write(image)
                self.frames[name].add(image.frame)
            except BaseException as error:
                self.errors.append(error)
            finally:
                self.condition.notify_all()

    def wait_for_frame(self, frame, *, timeout_s=10):
        deadline = monotonic() + timeout_s
        with self.condition:
            while True:
                if self.errors:
                    raise ValueError("Overtake source camera callback failed") from self.errors[0]
                if all(frame in observed for observed in self.frames.values()):
                    return
                remaining = deadline - monotonic()
                if remaining <= 0:
                    raise ValueError("Missing original overtake source camera frame")
                self.condition.wait(remaining)

    def verify(self, frames):
        expected = set(frames)
        if not expected or any(observed != expected for observed in self.frames.values()):
            raise ValueError("Missing or extra original overtake camera frames")
        return {name: len(expected) for name in CAMERAS}

    def close(self):
        if not self.closed:
            self.closed = True
            for sensor in reversed(self.sensors):
                sensor.stop()
                sensor.destroy()

"""Native same-direction two-lane overtaking route and return controller."""

from math import atan2, hypot


def _heading(waypoint):
    vector = waypoint.transform.get_forward_vector()
    norm = hypot(vector.x, vector.y)
    if norm < 1e-6:
        raise ValueError('Overtake road heading degenerate')
    return vector.x / norm, vector.y / norm


def select_overtake_route(world_map, *, step_m=2.5, steps=70):
    if step_m <= 0 or steps < 20:
        raise ValueError('Overtake route sampling invalid')
    for spawn in world_map.get_spawn_points():
        right = world_map.get_waypoint(spawn.location)
        if right is None or right.is_junction:
            continue
        left = right.get_left_lane()
        if (left is None or left.is_junction or left.road_id != right.road_id or
                _heading(left)[0] * _heading(right)[0] +
                _heading(left)[1] * _heading(right)[1] < .98):
            continue
        right_chain, left_chain = [right], [left]
        for _ in range(steps):
            choices = []
            for chain, first in ((right_chain, right), (left_chain, left)):
                next_same = [candidate for candidate in chain[-1].next(step_m)
                             if candidate.road_id == first.road_id and
                             candidate.lane_id == first.lane_id and
                             not candidate.is_junction]
                choices.append(next_same)
            if any(len(options) != 1 for options in choices):
                break
            right_chain.append(choices[0][0])
            left_chain.append(choices[1][0])
        if len(right_chain) == steps + 1:
            return {'right': right_chain, 'left': left_chain,
                    'road_id': right.road_id,
                    'right_lane_id': right.lane_id,
                    'left_lane_id': left.lane_id}
    raise ValueError('No connected same-direction left-passing lane pair')


def _point(waypoint):
    location = waypoint.transform.location
    return location.x, location.y


def choose_target(route, ego_xy, ego_rear_long_m, other_front_long_m,
                  *, passed_abreast=False, requested_return_clearance_m=3,
                  lookahead=3):
    if requested_return_clearance_m < 0 or lookahead < 1:
        raise ValueError('Overtake return parameters invalid')
    right = route['right']
    nearest = min(range(len(right)), key=lambda i: hypot(
        ego_xy[0] - _point(right[i])[0], ego_xy[1] - _point(right[i])[1]))
    index = min(nearest + lookahead, len(right) - 1)
    clear = (passed_abreast and
             ego_rear_long_m >= other_front_long_m + requested_return_clearance_m)
    return {'waypoint': (right if clear else route['left'])[index],
            'phase': 'return_right' if clear else 'pass_left',
            'waypoint_index': index,
            'measured_body_clearance_m': ego_rear_long_m - other_front_long_m}


def steer_speed_control(position_xy, heading_xy, velocity_xy, target_xy,
                        *, target_speed_mps=8):
    dx, dy = target_xy[0] - position_xy[0], target_xy[1] - position_xy[1]
    if hypot(dx, dy) < .2:
        raise ValueError('Overtake control target collapsed')
    hx, hy = heading_xy
    norm = hypot(hx, hy)
    if norm < 1e-6:
        raise ValueError('Overtake vehicle heading undefined')
    angle = atan2((hx * dy - hy * dx) / norm,
                  (hx * dx + hy * dy) / norm)
    speed = hypot(*velocity_xy)
    return {'steer': max(-.5, min(.5, .8 * angle)),
            'throttle': max(0., min(.5, .22 * (target_speed_mps - speed))),
            'brake': max(0., min(.5, .2 * (speed - target_speed_mps)))}

from pathlib import Path
from types import SimpleNamespace as NS
import sys
import unittest

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from overtake_camera import CAMERAS, OvertakeCameraCapture


class Sensor:
    def listen(self, callback):
        self.callback = callback

    def stop(self):
        pass

    def destroy(self):
        self.destroyed = True


class World:
    def __init__(self):
        self.sensors = []

    def get_blueprint_library(self):
        return NS(find=lambda _: NS(set_attribute=lambda *args: None))

    def spawn_actor(self, blueprint, transform, attach_to):
        sensor = Sensor()
        self.sensors.append(sensor)
        return sensor


class Sink:
    def __init__(self):
        self.frames = []

    def write(self, image):
        self.frames.append(image.frame)


class CameraTests(unittest.TestCase):
    def test_four_named_frames_and_missing_frame_rejection(self):
        world = World()
        carla = NS(Location=lambda *values: values, Rotation=lambda *values: values,
                   Transform=lambda location, rotation: (location, rotation))
        sinks = {name: Sink() for name in CAMERAS}
        capture = OvertakeCameraCapture(world, carla, object(), sinks)
        self.assertEqual(len(world.sensors), 4)
        for sensor, (name, spec) in zip(world.sensors, CAMERAS.items()):
            width, height = spec[2]
            sensor.callback(NS(frame=20, width=width, height=height))
        capture.wait_for_frame(20, timeout_s=.01)
        self.assertEqual(capture.verify([20]), {name: 1 for name in CAMERAS})
        with self.assertRaisesRegex(ValueError, 'Missing or extra'):
            capture.verify([20, 21])
        capture.close()
        self.assertTrue(all(sensor.destroyed for sensor in world.sensors))


if __name__ == '__main__':
    unittest.main()
